INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2432b538-f6fd-44d6-a85e-d2f8f69705ea', '六月三十日水亭送華陰王少府還縣', '六月三十日水亭送华陰王少府還縣', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["亭晚人將別，池涼酒未酣。","關門勞夕夢，仙掌引歸驂。","荷葉藏魚艇，藤花罥客簪。","殘雲收夏暑，新雨帶秋嵐。","失路情無適，離懷思不堪。","賴茲庭戶裏，別有小江潭。"]', '["亭晚人將別，池涼酒未酣。","关门勞夕梦，仙掌引归驂。","荷葉藏鱼艇，藤花罥客簪。","殘云收夏暑，新雨带秋嵐。","失路情無適，離懷思不堪。","賴茲庭戶裏，別有小江潭。"]', '诗', 'shi', '', NULL, '六月三十日水亭送華陰王少府還縣 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa61f46a-6f87-4787-9c14-396fc42ec775', '餞王岑判官赴襄陽道', '餞王岑判官赴襄陽道', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["故人漢陽使，走馬向南荆。","不厭楚山路，祗憐襄水清。","津頭習氏宅，江上夫人城。","夜入橘花宿，朝穿桐葉行。","害羣應自懾，持法固須平。","暫得青門醉，斜光速去程。"]', '["故人漢陽使，走马向南荆。","不厭楚山路，祗怜襄水清。","津头習氏宅，江上夫人城。","夜入橘花宿，朝穿桐葉行。","害羣應自懾，持法固須平。","暫得青门醉，斜光速去程。"]', '诗', 'shi', '', NULL, '餞王岑判官赴襄陽道 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca455938-5c6f-435c-bbea-02c8c5ec4987', '送薛弁歸河東', '送薛弁归河东', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["薛侯故鄉處，五老峰西頭。","歸路秦樹滅，到鄉河水流。","看君馬首去，滿耳蟬聲愁。","獻賦今未售，讀書凡幾秋。","應過伯夷廟，爲上關城樓。","樓上能相憶，西南指雍州。"]', '["薛侯故乡处，五老峰西头。","归路秦樹滅，到乡河水流。","看君马首去，满耳蟬声愁。","獻賦今未售，读书凡幾秋。","應過伯夷廟，爲上关城楼。","楼上能相憶，西南指雍州。"]', '诗', 'shi', '', NULL, '送薛弁歸河東 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2bd2129-8c45-436a-a416-e3e2d811020b', '送薛播擢第歸河東', '送薛播擢第归河东', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["歸去新戰勝，盛名人共聞。","鄉連渭川樹，家近條山雲。","夫子能好學，聖朝全用文。","弟兄負世譽，詞賦超人羣。","雨氣醒別酒，城陰低暮曛。","遙知出關後，更有一終軍。"]', '["归去新戰勝，盛名人共闻。","乡連渭川樹，家近條山云。","夫子能好学，聖朝全用文。","弟兄負世譽，词賦超人羣。","雨氣醒別酒，城陰低暮曛。","遙知出关後，更有一終軍。"]', '诗', 'shi', '', NULL, '送薛播擢第歸河東 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a225898-8d65-4977-b443-30f10dbde0bf', '送陶銑棄舉荆南覲省', '送陶銑棄舉荆南覲省', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["明時不愛璧，浪跡東南遊。","何必世人識，知君輕五侯。","采蘭度漢水，問絹過荆州。","異國有歸興，去鄉無客愁。","天寒楚塞雨，月淨襄陽秋。","坐見吾道遠，令人看白頭。"]', '["明时不愛璧，浪跡东南游。","何必世人識，知君轻五侯。","采蘭度漢水，问絹過荆州。","異国有归兴，去乡無客愁。","天寒楚塞雨，月淨襄陽秋。","坐见吾道远，令人看白头。"]', '诗', 'shi', '', NULL, '送陶銑棄舉荆南覲省 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58fedb5e-7b8a-4fdb-9529-aca2cb8eb60b', '送史司馬赴崔相公幕', '送史司马赴崔相公幕', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["崢嶸丞相府，清切鳳皇池。","羨爾瑤臺鶴，高棲瓊樹枝。","歸飛晴日好，吟弄惠風吹。","正有乘軒樂，初當學舞時。","珍禽在羅網，微命若遊絲。","願託周南羽，相銜谿水湄。"]', '["崢嶸丞相府，清切鳳皇池。","羨爾瑤台鹤，高棲瓊樹枝。","归飞晴日好，吟弄惠风吹。","正有乘軒乐，初當学舞时。","珍禽在羅網，微命若游絲。","願託周南羽，相銜谿水湄。"]', '诗', 'shi', '', NULL, '送史司馬赴崔相公幕 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4e10b1f-bafb-4ea4-92f3-d40856ddd214', '送嚴黃門拜御史大夫再鎮蜀川兼覲省', '送嚴黄门拜御史大夫再鎮蜀川兼覲省', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["授鉞辭金殿，承恩戀玉墀。","登壇漢主用，講德蜀人思。","副相韓安國，黃門向子期。","刀州重入夢，劒閣再題詞。","春草連青綬，晴花間赤旗。","山鶯朝送酒，江月夜供詩。","許國分憂日，榮親色養時。","蒼生望已久，來去不應遲。"]', '["授鉞辞金殿，承恩戀玉墀。","登壇漢主用，講德蜀人思。","副相韓安国，黄门向子期。","刀州重入梦，劒閣再題词。","春草連青綬，晴花间赤旗。","山鶯朝送酒，江月夜供诗。","許国分憂日，榮親色養时。","蒼生望已久，来去不應遲。"]', '诗', 'shi', '', NULL, '送嚴黃門拜御史大夫再鎮蜀川兼覲省 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8a68313-8ad3-4163-b301-e22f493e45de', '送郭僕射節制劒南', '送郭僕射節制劒南', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["鐵馬擐紅纓，幡旗出禁城。","明王親授鉞，丞相欲專征。","玉饌天廚送，金杯御酒傾。","劒門乘嶮過，閣道踏空行。","山鳥驚吹笛，江猿看洗兵。","曉雲隨去陣，夜月逐行營。","南仲今時往，西戎計日平。","將心感知己，萬里寄懸旌。"]', '["鐵马擐紅纓，幡旗出禁城。","明王親授鉞，丞相欲專征。","玉饌天廚送，金杯御酒傾。","劒门乘嶮過，閣道踏空行。","山鸟驚吹笛，江猿看洗兵。","晓云隨去陣，夜月逐行營。","南仲今时往，西戎計日平。","將心感知己，万里寄懸旌。"]', '诗', 'shi', '', NULL, '送郭僕射節制劒南 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc961fb7-c7d3-418f-8b14-7bb120d3f7ba', '早秋與諸子登虢州西亭觀眺', '早秋與諸子登虢州西亭观眺', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["亭高出鳥外，客到與雲齊。","樹點千家小，天圍萬嶺低。","殘[虹]挂陝北，急雨過關西。","酒榼緣青壁，瓜田傍綠谿。","微官何足道，愛客且相攜。","唯有鄉園處，依依望不迷。"]', '["亭高出鸟外，客到與云齊。","樹点千家小，天圍万嶺低。","殘[虹]挂陝北，急雨過关西。","酒榼緣青壁，瓜田傍綠谿。","微官何足道，愛客且相携。","唯有乡园处，依依望不迷。"]', '诗', 'shi', '', NULL, '早秋與諸子登虢州西亭觀眺 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecb34154-60f1-4f8d-a167-489f2cd60b56', '佐郡思舊遊', '佐郡思旧游', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["幸得趨紫殿，却憶侍丹墀。","史筆衆推直，諫書人莫窺。","平生恆自負，垂老此安卑。","同類皆先達，非才獨後時。","庭槐宿鳥亂，階草夜蟲悲。","白髮今無數，青雲未有期。"]', '["幸得趨紫殿，却憶侍丹墀。","史笔衆推直，諫书人莫窺。","平生恆自負，垂老此安卑。","同類皆先達，非才独後时。","庭槐宿鸟亂，階草夜蟲悲。","白髮今無數，青云未有期。"]', '诗', 'shi', '', NULL, '佐郡思舊遊 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aa486cf-d745-4fca-90c4-799fa58f6c6f', '滅胡曲', '滅胡曲', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["都護新滅胡，士馬氣亦麤。","蕭條虜塵淨，突兀天山孤。"]', '["都護新滅胡，士马氣亦麤。","蕭條虜塵淨，突兀天山孤。"]', '诗', 'shi', '', NULL, '滅胡曲 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9d8fa1b-854c-4aa5-aba7-aad8e5bb0860', '尚書念舊垂賜袍衣率題絕句獻上以申感謝', '尚书念旧垂賜袍衣率題絕句獻上以申感謝', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["富貴情還在，相逢豈間然。","綈袍更有贈，猶荷故人憐。"]', '["富貴情還在，相逢豈间然。","綈袍更有贈，猶荷故人怜。"]', '诗', 'shi', '', NULL, '尚書念舊垂賜袍衣率題絕句獻上以申感謝 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76a7946a-8034-45df-a629-e75080215821', '憶長安曲二章寄龐{氵寉} 一', '憶长安曲二章寄龐{氵寉} 一', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["東望望長安，正值日初出。","長安不可見，喜見長安日。"]', '["东望望长安，正值日初出。","长安不可见，喜见长安日。"]', '诗', 'shi', '', NULL, '憶長安曲二章寄龐{氵寉} 一 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1a56379-8eca-4fc8-8b53-d5b756292ff1', '憶長安曲二章寄龐{氵寉} 二', '憶长安曲二章寄龐{氵寉} 二', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["長安何處在，只在馬蹄下。","明日歸長安，爲君急走馬。"]', '["长安何处在，只在马蹄下。","明日归长安，爲君急走马。"]', '诗', 'shi', '', NULL, '憶長安曲二章寄龐{氵寉} 二 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68d87256-cfc3-4a7f-b4e8-4d630f7127f7', '寄韓樽', '寄韓樽', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["夫子素多疾，別來未得書。","北庭苦寒地，體內今何如。"]', '["夫子素多疾，別来未得书。","北庭苦寒地，體內今何如。"]', '诗', 'shi', '', NULL, '寄韓樽 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83bd1fb1-c1db-4146-8f33-af165bbd365c', '醉裏送裴子赴鎮西', '醉裏送裴子赴鎮西', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["醉後未能別，待醒方送君。","看君走馬去，直上天山雲。"]', '["醉後未能別，待醒方送君。","看君走马去，直上天山云。"]', '诗', 'shi', '', NULL, '醉裏送裴子赴鎮西 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bad85cd5-0c5a-44a9-b54d-d228171e0703', '題井陘雙谿李道士所居', '題井陘雙谿李道士所居', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["五粒松花酒，雙谿道士家。","唯求縮却地，鄉路莫教賒。"]', '["五粒松花酒，雙谿道士家。","唯求縮却地，乡路莫教賒。"]', '诗', 'shi', '', NULL, '題井陘雙谿李道士所居 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eac84d5-a708-48f4-a104-da60f83fa21c', '題雲際南峰眼上人讀經堂', '題云際南峰眼上人读經堂', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["結宇題三藏，焚香老一峰。","雲間獨坐臥，祗是對山松。"]', '["結宇題三藏，焚香老一峰。","云间独坐臥，祗是对山松。"]', '诗', 'shi', '', NULL, '題雲際南峰眼上人讀經堂 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90c23748-9d7c-4387-9822-3961851ae508', '題梁鍠城中高居', '題梁鍠城中高居', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["高住最高處，千家恆眼前。","題詩飲酒後，只對諸峰眠。"]', '["高住最高处，千家恆眼前。","題诗饮酒後，只对諸峰眠。"]', '诗', 'shi', '', NULL, '題梁鍠城中高居 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb899b8b-f88d-4114-9041-e72fa5857add', '題三會寺蒼頡造字臺', '題三會寺蒼頡造字台', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["野寺荒臺晚，寒天古木悲。","空堦有鳥跡，猶似造書時。"]', '["野寺荒台晚，寒天古木悲。","空堦有鸟跡，猶似造书时。"]', '诗', 'shi', '', NULL, '題三會寺蒼頡造字臺 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b5c5e60-b396-4124-bffe-89034bba8da2', '日沒賀延磧作', '日沒賀延磧作', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["沙上見日出，沙上見日沒。","悔向萬里來，功名是何物。"]', '["沙上见日出，沙上见日沒。","悔向万里来，功名是何物。"]', '诗', 'shi', '', NULL, '日沒賀延磧作 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c69f17df-0d79-4631-bac2-100b3b02e7a4', '西過渭州見渭水思秦川', '西過渭州见渭水思秦川', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["渭水東流去，何時到雍州。","憑添兩行淚，寄向故園流。"]', '["渭水东流去，何时到雍州。","憑添兩行泪，寄向故园流。"]', '诗', 'shi', '', NULL, '西過渭州見渭水思秦川 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbccfefb-be87-4032-ab99-f3c01b3d3aaf', '經隴頭分水', '經隴头分水', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["隴水何年有，潺潺逼路傍。","東西流不歇，曾斷幾人腸。"]', '["隴水何年有，潺潺逼路傍。","东西流不歇，曾斷幾人腸。"]', '诗', 'shi', '', NULL, '經隴頭分水 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1befd532-6d9d-4c86-9d3a-d65ebcf74f1c', '秋思', '秋思', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["那知芳歲晚，坐見寒葉墮。","吾不如腐草，翻飛作螢火。"]', '["那知芳歲晚，坐见寒葉墮。","吾不如腐草，翻飞作螢火。"]', '诗', 'shi', '', NULL, '秋思 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da3b4635-ab06-48e2-b59f-478803c7fb19', '行軍九日思長安故園', '行軍九日思长安故园', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["強欲登高去，無人送酒來。","遙憐故園菊，應傍戰場開。"]', '["強欲登高去，無人送酒来。","遙怜故园菊，應傍戰場开。"]', '诗', 'shi', '', NULL, '行軍九日思長安故園 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82c4ddaa-0284-40bf-9c93-d9d222fe1ad5', '戲題關門', '戲題关门', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["來亦一布衣，去亦一布衣。","羞見關城吏，還從舊路歸。"]', '["来亦一布衣，去亦一布衣。","羞见关城吏，還從旧路归。"]', '诗', 'shi', '', NULL, '戲題關門 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfa3e9ee-7dce-4085-af9f-e634f83c4426', '歎白髮', '歎白髮', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["白髮生偏速，交人不奈何。","今朝兩鬢上，更較數莖多。"]', '["白髮生偏速，交人不奈何。","今朝兩鬢上，更較數莖多。"]', '诗', 'shi', '', NULL, '歎白髮 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60ef952f-0009-429a-bf08-6e787f06221f', '題平陽郡汾橋邊柳樹', '題平陽郡汾橋邊柳樹', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["此地曾居住，今來宛似歸。","可憐汾上柳，相見也依依。"]', '["此地曾居住，今来宛似归。","可怜汾上柳，相见也依依。"]', '诗', 'shi', '', NULL, '題平陽郡汾橋邊柳樹 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19aa71bb-253b-4a46-9562-d669ef15e5a6', '失題', '失題', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["帝鄉北近日，瀘口南連蠻。","何當遇長房，縮地到京關。"]', '["帝乡北近日，瀘口南連蠻。","何當遇长房，縮地到京关。"]', '诗', 'shi', '', NULL, '失題 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('772e35bb-d32e-46cf-90dd-2dc214094b28', '獻封大夫破播仙凱歌六首 一', '獻封大夫破播仙凱歌六首 一', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["漢將承恩西破戎，捷書先奏未央宮。","天子預開麟閣待，祗今誰數貳師功。"]', '["漢將承恩西破戎，捷书先奏未央宮。","天子預开麟閣待，祗今誰數貳師功。"]', '诗', 'shi', '', NULL, '獻封大夫破播仙凱歌六首 一 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a63b4c45-1a19-4ba1-ac68-55fa1a556680', '獻封大夫破播仙凱歌六首 二', '獻封大夫破播仙凱歌六首 二', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["官軍西出過樓蘭，營幕傍臨月窟寒。","蒲海曉霜凝馬尾，葱山夜雪撲旌竿。"]', '["官軍西出過楼蘭，營幕傍臨月窟寒。","蒲海晓霜凝马尾，葱山夜雪撲旌竿。"]', '诗', 'shi', '', NULL, '獻封大夫破播仙凱歌六首 二 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07f6c6be-9cba-41a2-8977-501e4f6a4e7a', '獻封大夫破播仙凱歌六首 三', '獻封大夫破播仙凱歌六首 三', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["鳴笳疊鼓擁回軍，破國平蕃昔未聞。","丈夫鵲印搖邊月，大將龍旗掣海雲。"]', '["鳴笳叠鼓擁回軍，破国平蕃昔未闻。","丈夫鵲印搖邊月，大將龙旗掣海云。"]', '诗', 'shi', '', NULL, '獻封大夫破播仙凱歌六首 三 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d43e23b5-21f6-4242-a5df-4135367a1465', '獻封大夫破播仙凱歌六首 四', '獻封大夫破播仙凱歌六首 四', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["日落轅門鼓角鳴，千羣面縛出蕃城。","洗兵魚海雲迎陣，秣馬龍堆月照營。"]', '["日落轅门鼓角鳴，千羣面縛出蕃城。","洗兵鱼海云迎陣，秣马龙堆月照營。"]', '诗', 'shi', '', NULL, '獻封大夫破播仙凱歌六首 四 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4254a7b3-9e7e-499c-a8fd-9ae75962cf07', '獻封大夫破播仙凱歌六首 五', '獻封大夫破播仙凱歌六首 五', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["蕃軍遙見漢家營，滿谷連山遍哭聲。","萬箭千刀一夜殺，平明流血浸空城。"]', '["蕃軍遙见漢家營，满谷連山遍哭声。","万箭千刀一夜殺，平明流血浸空城。"]', '诗', 'shi', '', NULL, '獻封大夫破播仙凱歌六首 五 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cb862b1-db8d-4dee-8b35-00a19a983e8b', '獻封大夫破播仙凱歌六首 六', '獻封大夫破播仙凱歌六首 六', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["暮雨旌旗濕未乾，胡煙白草日光寒。","昨夜將軍連曉戰，蕃軍只見馬空鞍。"]', '["暮雨旌旗濕未乾，胡煙白草日光寒。","昨夜將軍連晓戰，蕃軍只见马空鞍。"]', '诗', 'shi', '', NULL, '獻封大夫破播仙凱歌六首 六 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('226acd85-80b0-4dd1-9c95-d754e4177886', '春興戲題贈李侯', '春兴戲題贈李侯', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["黃雀始欲銜花來，君家種桃花未開。","長安二月眼看盡，寄報春風早爲催。"]', '["黄雀始欲銜花来，君家種桃花未开。","长安二月眼看尽，寄報春风早爲催。"]', '诗', 'shi', '', NULL, '春興戲題贈李侯 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f95a149a-4639-4542-a8d9-e9e1086d8d79', '過燕支寄杜位', '過燕支寄杜位', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["燕支山西酒泉道，北風吹沙卷白草。","長安遙在日光邊，憶君不見令人老。"]', '["燕支山西酒泉道，北风吹沙卷白草。","长安遙在日光邊，憶君不见令人老。"]', '诗', 'shi', '', NULL, '過燕支寄杜位 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36a888e3-78ab-430d-975a-f36ae81f59d8', '題苜蓿峰寄家人', '題苜蓿峰寄家人', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["苜蓿峰邊逢立春，胡蘆河上淚沾巾。","閨中只是空相憶，不見沙場愁殺人。"]', '["苜蓿峰邊逢立春，胡蘆河上泪沾巾。","閨中只是空相憶，不见沙場愁殺人。"]', '诗', 'shi', '', NULL, '題苜蓿峰寄家人 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c470424-c001-4057-a675-55f2a509d945', '玉關寄長安李主簿', '玉关寄长安李主簿', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["東去長安萬里餘，故人何惜一行書。","玉關西望堪腸斷，況復明朝是歲除。"]', '["东去长安万里餘，故人何惜一行书。","玉关西望堪腸斷，況复明朝是歲除。"]', '诗', 'shi', '', NULL, '玉關寄長安李主簿 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0b83d31-5e1a-4da1-ba34-9ab5ab6f93a3', '武威送劉判官赴磧西行軍', '武威送劉判官赴磧西行軍', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["火山五月行人少，看君馬去疾如鳥。","都護行營太白西，角聲一動胡天曉。"]', '["火山五月行人少，看君马去疾如鸟。","都護行營太白西，角声一动胡天晓。"]', '诗', 'shi', '', NULL, '武威送劉判官赴磧西行軍 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a772df1-0c2e-4e96-96a8-1704bffd3921', '虢州後亭送李判官使赴晉絳', '虢州後亭送李判官使赴晉絳', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["西原驛路挂城頭，客散紅亭雨未收。","君去試看汾水上，白雲猶似漢時秋。"]', '["西原驛路挂城头，客散紅亭雨未收。","君去試看汾水上，白云猶似漢时秋。"]', '诗', 'shi', '', NULL, '虢州後亭送李判官使赴晉絳 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('739e76d0-a70a-4018-969d-3d24d9dcd96b', '五月四日送王少府歸華陰', '五月四日送王少府归华陰', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["仙掌分明引馬頭，西看一點是關樓。","五月也須應到舍，知君不肯更淹留。"]', '["仙掌分明引马头，西看一点是关楼。","五月也須應到舍，知君不肯更淹留。"]', '诗', 'shi', '', NULL, '五月四日送王少府歸華陰 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ce28c74-d2fa-4f33-845d-08e908b3c974', '原頭送范侍御', '原头送范侍御', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["百尺原頭酒色殷，路傍驄馬汗斑斑。","別君祇有相思夢，遮莫千山與萬山。"]', '["百尺原头酒色殷，路傍驄马汗斑斑。","別君祇有相思梦，遮莫千山與万山。"]', '诗', 'shi', '', NULL, '原頭送范侍御 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17c18673-7c7e-42fa-bda0-f6e69ed7b370', '送李明府赴睦州便拜覲太夫人', '送李明府赴睦州便拜覲太夫人', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["手把銅章望海雲，夫人江上泣羅帬。","嚴灘一點舟中月，萬里煙波也夢君。"]', '["手把銅章望海云，夫人江上泣羅帬。","嚴灘一点舟中月，万里煙波也梦君。"]', '诗', 'shi', '', NULL, '送李明府赴睦州便拜覲太夫人 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eee95579-e80d-42e4-9585-54b468ce3c60', '虢州西山亭子送范端公', '虢州西山亭子送范端公', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["百尺紅亭對萬峰，平明相送到齋鐘。","驄馬勸君皆卸却，使君家醞舊來濃。"]', '["百尺紅亭对万峰，平明相送到斋鐘。","驄马勸君皆卸却，使君家醞旧来濃。"]', '诗', 'shi', '', NULL, '虢州西山亭子送范端公 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e9c13e8-1165-4900-81c2-1d00c2100ec1', '奉送賈侍御使江外', '奉送賈侍御使江外', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["新騎驄馬復承恩，使出金陵過海門。","荆南渭北難相見，莫惜衫襟着酒痕。"]', '["新騎驄马复承恩，使出金陵過海门。","荆南渭北难相见，莫惜衫襟着酒痕。"]', '诗', 'shi', '', NULL, '奉送賈侍御使江外 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('470e2155-440b-4ed9-8ba5-2fcc13618d36', '崔倉曹席上送殷寅充石相判官赴淮南', '崔倉曹席上送殷寅充石相判官赴淮南', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["清淮無底綠江深，宿處津亭楓樹林。","駟馬欲辭丞相府，一樽須盡故人心。"]', '["清淮無底綠江深，宿处津亭楓樹林。","駟马欲辞丞相府，一樽須尽故人心。"]', '诗', 'shi', '', NULL, '崔倉曹席上送殷寅充石相判官赴淮南 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f3bf9dd-4411-44eb-a29c-f7661d83f523', '送崔子還京', '送崔子還京', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["匹馬西從天外歸，揚鞭只共鳥爭飛。","送君九月交河北，雪裏題詩淚滿衣。"]', '["匹马西從天外归，揚鞭只共鸟爭飞。","送君九月交河北，雪裏題诗泪满衣。"]', '诗', 'shi', '', NULL, '送崔子還京 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9c9beba-7b99-46c8-a5e4-369cd647a307', '酒泉太守席上醉後作', '酒泉太守席上醉後作', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["酒泉太守能劒舞，高堂置酒夜擊鼓。","胡笳一曲斷人腸，座上相看淚如雨。"]', '["酒泉太守能劒舞，高堂置酒夜擊鼓。","胡笳一曲斷人腸，座上相看泪如雨。"]', '诗', 'shi', '', NULL, '酒泉太守席上醉後作 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8610faee-9b2d-4656-beef-3b05d26a09d1', '題觀樓', '題观楼', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["荒樓荒井閉空山，關令乘雲去不還。","羽蓋霓旌何處在，空留藥臼向人間。"]', '["荒楼荒井閉空山，关令乘云去不還。","羽蓋霓旌何处在，空留藥臼向人间。"]', '诗', 'shi', '', NULL, '題觀樓 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ece2f410-a1f2-49a0-8ef3-e6bf8b14da3c', '草堂村尋羅生不遇', '草堂村尋羅生不遇', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["數株谿柳色依依，深巷斜陽暮鳥飛。","門前雪滿無人迹，應是先生出未歸。"]', '["數株谿柳色依依，深巷斜陽暮鸟飞。","门前雪满無人迹，應是先生出未归。"]', '诗', 'shi', '', NULL, '草堂村尋羅生不遇 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8db4f6e8-c34f-4eca-8543-8895d965330e', '山房春事二首 一', '山房春事二首 一', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["風恬日暖蕩春光，戲蝶遊蜂亂入房。","數枝門柳低衣桁，一片山花落筆牀。"]', '["风恬日暖蕩春光，戲蝶游蜂亂入房。","數枝门柳低衣桁，一片山花落笔牀。"]', '诗', 'shi', '', NULL, '山房春事二首 一 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19a6f2b8-9082-4ecb-8efe-9547068c9d4e', '山房春事二首 二', '山房春事二首 二', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["梁園日暮亂飛鴉，極目蕭條三兩家。","庭樹不知人死盡，春來還發舊時花。"]', '["梁园日暮亂飞鴉，極目蕭條三兩家。","庭樹不知人死尽，春来還發旧时花。"]', '诗', 'shi', '', NULL, '山房春事二首 二 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07238ad9-c348-43d4-b1d7-25d89369286d', '逢入京使', '逢入京使', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["故園東望路漫漫，雙袖龍鍾淚不乾。","馬上相逢無紙筆，憑君傳語報平安。"]', '["故园东望路漫漫，雙袖龙鍾泪不乾。","马上相逢無紙笔，憑君傳語報平安。"]', '诗', 'shi', '', NULL, '逢入京使 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4e1e3a8-2e62-43bc-96fc-4fe643d6356d', '過磧', '過磧', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["黃沙磧裏客行迷，四望雲天直下低。","爲言地盡天還盡，行到安西更向西。"]', '["黄沙磧裏客行迷，四望云天直下低。","爲言地尽天還尽，行到安西更向西。"]', '诗', 'shi', '', NULL, '過磧 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55193000-bdec-46d5-8607-e1af8a1ca91d', '磧中作', '磧中作', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["走馬西來欲到天，辭家見月兩回圓。","今夜不知何處宿，平沙萬里絕人煙。"]', '["走马西来欲到天，辞家见月兩回圓。","今夜不知何处宿，平沙万里絕人煙。"]', '诗', 'shi', '', NULL, '磧中作 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1075d5a8-384f-4b8b-a3b5-3832b468a2f7', '赴北庭度隴思家', '赴北庭度隴思家', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["西向輪臺萬里馀，也知鄉信日應疎。","隴山鸚鵡能言語，爲報家人數寄書。"]', '["西向輪台万里馀，也知乡信日應疎。","隴山鸚鵡能言語，爲報家人數寄书。"]', '诗', 'shi', '', NULL, '赴北庭度隴思家 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b740324c-29e9-4cba-b1db-dece09859ea5', '胡歌', '胡歌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["黑姓蕃王貂鼠裘，葡萄宮錦醉纏頭。","關西老將能苦戰，七十行兵仍未休。"]', '["黑姓蕃王貂鼠裘，葡萄宮錦醉纏头。","关西老將能苦戰，七十行兵仍未休。"]', '诗', 'shi', '', NULL, '胡歌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c790d18-27ef-40d3-a456-7e72161aad46', '趙將軍歌', '趙將軍歌', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["九月天山風似刀，城南獵馬縮寒毛。","將軍縱博場場勝，賭得單于貂鼠袍。"]', '["九月天山风似刀，城南獵马縮寒毛。","將軍縱博場場勝，賭得單于貂鼠袍。"]', '诗', 'shi', '', NULL, '趙將軍歌 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e9f5ac2-4631-4b79-80d1-3111f8caf8b8', '醉戲竇子美人', '醉戲竇子美人', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["朱脣一點桃花殷，宿妝嬌羞偏髻鬟。","細看只似陽臺女，醉着莫許歸巫山。"]', '["朱脣一点桃花殷，宿妝嬌羞偏髻鬟。","細看只似陽台女，醉着莫許归巫山。"]', '诗', 'shi', '', NULL, '醉戲竇子美人 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7447d48d-2f26-4359-8818-4da63b04ae93', '秋夜聞笛', '秋夜闻笛', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["天門街西聞搗帛，一夜愁殺湘南客。","長安城中百萬家，不知何人吹夜笛。"]', '["天门街西闻捣帛，一夜愁殺湘南客。","长安城中百万家，不知何人吹夜笛。"]', '诗', 'shi', '', NULL, '秋夜聞笛 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c016ed11-0403-48a8-962d-ab72b53ad672', '戲問花門酒家翁', '戲问花门酒家翁', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["老人七十仍沽酒，千壺百甕花門口。","道傍榆莢仍似錢，摘來沽酒君肯否。"]', '["老人七十仍沽酒，千壺百甕花门口。","道傍榆莢仍似錢，摘来沽酒君肯否。"]', '诗', 'shi', '', NULL, '戲問花門酒家翁 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea65262c-da6d-4dd8-a8b3-01b6679f9600', '春夢', '春梦', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["洞房昨夜春風起，故人尚隔湘江水。","枕上片時春夢中，行盡江南數千里。"]', '["洞房昨夜春风起，故人尚隔湘江水。","枕上片时春梦中，行尽江南數千里。"]', '诗', 'shi', '', NULL, '春夢 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9a9f785-80e0-49ca-9a0a-3655b89f92b5', '冬夕', '冬夕', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["浩汗霜風刮天地，溫泉火井無生意。","澤國龍蛇凍不伸，南山瘦柏消殘翠。"]', '["浩汗霜风刮天地，溫泉火井無生意。","澤国龙蛇凍不伸，南山瘦柏消殘翠。"]', '诗', 'shi', '', NULL, '冬夕 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('594804c8-cde2-49ac-9a7c-247580612be0', '句', '句', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["初程莫早發，且宿灞橋頭。"]', '["初程莫早發，且宿灞橋头。"]', '诗', 'shi', '', NULL, '句 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4de4511-6b01-4351-ace2-e815683cd9fd', '武陽送別', '武陽送別', 'ba10b84a-0de5-48a7-b595-6bcd7fd71b66', '唐', '["菊黃蘆白雁初飛，羌笛胡笳淚滿衣。","送君腸斷秋江水，一去東流何日歸。"]', '["菊黄蘆白雁初飞，羌笛胡笳泪满衣。","送君腸斷秋江水，一去东流何日归。"]', '诗', 'shi', '', NULL, '武陽送別 沈宇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7084f140-821f-484d-803d-264dd8b3f38e', '擣衣', '擣衣', 'ba10b84a-0de5-48a7-b595-6bcd7fd71b66', '唐', '["日暮遠天青，霜風入後庭。","洞房寒未掩，砧杵夜泠泠。"]', '["日暮远天青，霜风入後庭。","洞房寒未掩，砧杵夜泠泠。"]', '诗', 'shi', '', NULL, '擣衣 沈宇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5659042a-a8b9-4273-9933-9ed6f029ec53', '代閨人', '代閨人', 'ba10b84a-0de5-48a7-b595-6bcd7fd71b66', '唐', '["楊柳青青鳥亂吟，春風香靄洞房深。","百花簾下朝窺鏡，明月窗前夜理琴。"]', '["楊柳青青鸟亂吟，春风香靄洞房深。","百花簾下朝窺镜，明月窗前夜理琴。"]', '诗', 'shi', '', NULL, '代閨人 沈宇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3207ad7-1469-4972-aa85-401f32839694', '江南遇雨', '江南遇雨', '4a94c648-4c3d-43bc-badc-e28b176dc769', '唐', '["江天寒意少，冬月雨仍飛。","出戶愁爲聽，從風灑客衣。","旅魂驚處斷，鄉信意中微。","幾日應晴去，孤舟且欲歸。"]', '["江天寒意少，冬月雨仍飞。","出戶愁爲听，從风灑客衣。","旅魂驚处斷，乡信意中微。","幾日應晴去，孤舟且欲归。"]', '诗', 'shi', '', NULL, '江南遇雨 張鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75f7f55a-0a4c-4143-b875-9eb6748524a7', '鄴城引', '鄴城引', '4a94c648-4c3d-43bc-badc-e28b176dc769', '唐', '["君不見漢家失統三靈變，魏武爭雄六龍戰。","盪海吞江制中國，迴天運斗應南面。","隱隱都城紫陽開，迢迢分野黃星見。","流年不駐漳河水，明月俄終鄴國宴。","文章猶入管弦新，帷座空銷狐兔塵。","可惜望陵歌舞處，松風四面暮愁人。"]', '["君不见漢家失統三靈变，魏武爭雄六龙戰。","盪海吞江制中国，迴天運斗應南面。","隐隐都城紫陽开，迢迢分野黄星见。","流年不駐漳河水，明月俄終鄴国宴。","文章猶入管弦新，帷座空銷狐兔塵。","可惜望陵歌舞处，松风四面暮愁人。"]', '诗', 'shi', '', NULL, '鄴城引 張鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a45af21-cd88-4ab5-9d93-2e8223009b0f', '僧舍小池', '僧舍小池', '4a94c648-4c3d-43bc-badc-e28b176dc769', '唐', '["引出白雲根，潺潺漲蘚痕。","冷光搖砌錫，疎影露枝猿。","淨帶凋霜葉，香通洗藥源。","貝多文字古，宜向此中翻。"]', '["引出白云根，潺潺漲蘚痕。","冷光搖砌錫，疎影露枝猿。","淨带凋霜葉，香通洗藥源。","貝多文字古，宜向此中翻。"]', '诗', 'shi', '', NULL, '僧舍小池 張鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14f08803-4994-4388-b9f2-ecc9d5afaf44', '擬古', '擬古', 'af2ae106-22ea-433d-b512-655de7861770', '唐', '["沙塵朝蔽日，失道還相遇。","寒影波上雲，秋聲月前樹。","川氣生曉夕，野陰乍煙霧。","沈沈滮池水，人馬不敢渡。","吮癰世所薄，挾纊恩難顧。","不見古時人，中宵淚橫注。"]', '["沙塵朝蔽日，失道還相遇。","寒影波上云，秋声月前樹。","川氣生晓夕，野陰乍煙霧。","沈沈滮池水，人马不敢渡。","吮癰世所薄，挾纊恩难顧。","不见古时人，中宵泪橫注。"]', '诗', 'shi', '', NULL, '擬古 薛奇童 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83de871a-bfe4-427e-b8ec-7970c03bdb02', '和李起居秋夜之作', '和李起居秋夜之作', 'af2ae106-22ea-433d-b512-655de7861770', '唐', '["過庭聞禮日，趨侍記言回。","獨臥玉窗前，卷簾殘雨來。","高秋南斗轉，涼夜北堂開。","水影入朱戶，螢光生綠苔。","簡成良史筆，年是洛陽才。","莫重白雲意，時人許上台。"]', '["過庭闻禮日，趨侍記言回。","独臥玉窗前，卷簾殘雨来。","高秋南斗轉，涼夜北堂开。","水影入朱戶，螢光生綠苔。","簡成良史笔，年是洛陽才。","莫重白云意，时人許上台。"]', '诗', 'shi', '', NULL, '和李起居秋夜之作 薛奇童 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6e46fc0-bd5e-4430-8362-a4fe114aa64a', '吳聲子夜歌', '吳声子夜歌', 'af2ae106-22ea-433d-b512-655de7861770', '唐', '["淨掃黃金堦，飛霜皓如雪。","下簾彈箜篌，不忍見秋月。"]', '["淨掃黄金堦，飞霜皓如雪。","下簾彈箜篌，不忍见秋月。"]', '诗', 'shi', '', NULL, '吳聲子夜歌 薛奇童 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f430f46-2fa6-451a-9c5a-184ebc38291c', '塞下曲', '塞下曲', 'af2ae106-22ea-433d-b512-655de7861770', '唐', '["驕虜初南下，煙塵暗國中。","獨召李將軍，夜開甘泉宮。","一身許明主，萬里總元戎。","霜甲臥不暖，夜半聞邊風。","胡天早飛雪，荒徼多轉蓬。","寒雲覆水重，秋氣連海空。","金鞍誰家子，上馬鳴角弓。","自是幽幷客，非論愛立功。"]', '["驕虜初南下，煙塵暗国中。","独召李將軍，夜开甘泉宮。","一身許明主，万里總元戎。","霜甲臥不暖，夜半闻邊风。","胡天早飞雪，荒徼多轉蓬。","寒云覆水重，秋氣連海空。","金鞍誰家子，上马鳴角弓。","自是幽幷客，非論愛立功。"]', '诗', 'shi', '', NULL, '塞下曲 薛奇童 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d713366-1776-4789-aafa-11c9c859e818', '雲中行', '云中行', 'af2ae106-22ea-433d-b512-655de7861770', '唐', '["雲中小兒吹金管，向晚因風一川滿。","塞北雲高心已悲，城南木落腸堪斷。","憶昔魏家都此方，涼風觀前朝百王。","千門曉映山川色，雙闕遙連日月光。","舉杯稱壽永相保，日夕歌鐘徹清昊。","將軍汗馬百戰塲，天子射獸五原草。","寂寞金輿去不歸，陵上黃塵滿路飛。","河邊不語傷流水，川上含情歎落暉。","此時獨立無所見，日暮寒風吹客衣。"]', '["云中小兒吹金管，向晚因风一川满。","塞北云高心已悲，城南木落腸堪斷。","憶昔魏家都此方，涼风观前朝百王。","千门晓映山川色，雙闕遙連日月光。","舉杯稱壽永相保，日夕歌鐘徹清昊。","將軍汗马百戰塲，天子射獸五原草。","寂寞金輿去不归，陵上黄塵满路飞。","河邊不語傷流水，川上含情歎落暉。","此时独立無所见，日暮寒风吹客衣。"]', '诗', 'shi', '', NULL, '雲中行 薛奇童 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6baf8d34-95ce-48e8-92dc-4fb311733d65', '楚宮詞二首 一', '楚宮词二首 一', 'af2ae106-22ea-433d-b512-655de7861770', '唐', '["禁苑春風起，流鶯繞合歡。","玉窗通日氣，珠箔捲輕寒。","楊葉垂陰砌，梨花入井闌。","君王好長袖，新作舞衣寬。"]', '["禁苑春风起，流鶯繞合歡。","玉窗通日氣，珠箔捲轻寒。","楊葉垂陰砌，梨花入井闌。","君王好长袖，新作舞衣寬。"]', '诗', 'shi', '', NULL, '楚宮詞二首 一 薛奇童 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('441151ec-b4e4-46ed-9e6f-da73a66d4726', '楚宮詞二首 二', '楚宮词二首 二', 'af2ae106-22ea-433d-b512-655de7861770', '唐', '["日晚梧桐落，微寒入禁垣。","月懸三雀觀，霜度萬秋門。","豔舞矜新寵，愁容泣舊恩。","不堪深殿裏，簾外欲黃昏。"]', '["日晚梧桐落，微寒入禁垣。","月懸三雀观，霜度万秋门。","豔舞矜新寵，愁容泣旧恩。","不堪深殿裏，簾外欲黄昏。"]', '诗', 'shi', '', NULL, '楚宮詞二首 二 薛奇童 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('950b38bc-861c-42f8-baf8-1a49ccdd642a', '長孫十一東山春夜見贈', '长孫十一东山春夜见贈', 'ed94aa46-63bf-4681-b91f-fa9e9bf369ba', '唐', '["故人謝城闕，揮手碧雲期。","谿月照隱處，松風生興時。","舊林日云暮，芳草歲空滋。","甘與子成夢，請君同所思。"]', '["故人謝城闕，揮手碧云期。","谿月照隐处，松风生兴时。","旧林日云暮，芳草歲空滋。","甘與子成梦，請君同所思。"]', '诗', 'shi', '', NULL, '長孫十一東山春夜見贈 楊諫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26fca58d-fd6f-4950-a2f5-041536701426', '贈知己', '贈知己', 'ed94aa46-63bf-4681-b91f-fa9e9bf369ba', '唐', '["江南折芳草，江北贈佳期。","江闊水復急，過江常苦遲。","蘋白蘭葉青，恐度先香時。","美人碧雲外，寧見長相思。"]', '["江南折芳草，江北贈佳期。","江闊水复急，過江常苦遲。","蘋白蘭葉青，恐度先香时。","美人碧云外，寧见长相思。"]', '诗', 'shi', '', NULL, '贈知己 楊諫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f7cb262-1b86-4ee6-bf4f-7dd4fe870f1e', '東溪待蘇戶曹不至', '东溪待蘇戶曹不至', '1686091c-4c95-4704-b163-1d2c0817c51d', '唐', '["洛陽城東伊水西，千花萬竹使人迷。","臺上柳枝臨岸低，門前荷葉與橋齊。","日暮待君君不見，長風吹雨過青溪。"]', '["洛陽城东伊水西，千花万竹使人迷。","台上柳枝臨岸低，门前荷葉與橋齊。","日暮待君君不见，长风吹雨過青溪。"]', '诗', 'shi', '', NULL, '東溪待蘇戶曹不至 張萬頃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d50cfa2-8adb-45da-b0da-c55b4b596f08', '登天目山下作', '登天目山下作', '1686091c-4c95-4704-b163-1d2c0817c51d', '唐', '["去歲離秦望，今冬使楚關。","淚添天目水，髮變海頭山。","別母烏南逝，辭兄雁北還。","宦遊偏不樂，長爲憶慈顏。"]', '["去歲離秦望，今冬使楚关。","泪添天目水，髮变海头山。","別母烏南逝，辞兄雁北還。","宦游偏不乐，长爲憶慈顏。"]', '诗', 'shi', '', NULL, '登天目山下作 張萬頃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('709b7db4-b6be-4473-b68a-392ea987f02c', '送裴少府', '送裴少府', '1686091c-4c95-4704-b163-1d2c0817c51d', '唐', '["夕膳望東周，晨裝不少留。","酒中同樂事，關外越離憂。","座濕秦山雨，庭寒渭水秋。","何當鷹隼擊，來拂故林游。"]', '["夕膳望东周，晨裝不少留。","酒中同乐事，关外越離憂。","座濕秦山雨，庭寒渭水秋。","何當鷹隼擊，来拂故林游。"]', '诗', 'shi', '', NULL, '送裴少府 張萬頃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('626af69c-a8ce-4e3b-b32e-cac4fad660f4', '旅次灞亭', '旅次灞亭', '46381756-1cf4-4973-8530-778cfa0eaa4c', '唐', '["閑琴開旅思，清夜有愁心。","圓月正當戶，微風猶在林。","蒼茫孤亭上，歷亂多秋音。","言念待明發，東山幽意深。"]', '["闲琴开旅思，清夜有愁心。","圓月正當戶，微风猶在林。","蒼茫孤亭上，歷亂多秋音。","言念待明發，东山幽意深。"]', '诗', 'shi', '', NULL, '旅次灞亭 沈頌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f47b9fd7-99c3-42d9-9c0d-b0b955bd014f', '春旦歌', '春旦歌', '46381756-1cf4-4973-8530-778cfa0eaa4c', '唐', '["常聞嬴女玉簫臺，奏曲情深彩鳳來。","欲登此地銷歸恨，却羨雙飛去不回。"]', '["常闻嬴女玉簫台，奏曲情深彩鳳来。","欲登此地銷归恨，却羨雙飞去不回。"]', '诗', 'shi', '', NULL, '春旦歌 沈頌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdb37947-dfae-4cdb-a0fe-5c6deff898a9', '早發西山', '早發西山', '46381756-1cf4-4973-8530-778cfa0eaa4c', '唐', '["游子空有懷，賞心杳無路。","前程數千里，乘夜連輕馭。","繚繞松篠中，蒼茫猶未曙。","遙聞孤村犬，暗指人家去。","疲馬懷澗泉，征衣犯霜露。","喧呼谿鳥驚，沙上或鶱翥。","娟娟東岑月，照耀獨歸慮。"]', '["游子空有懷，賞心杳無路。","前程數千里，乘夜連轻馭。","繚繞松篠中，蒼茫猶未曙。","遙闻孤村犬，暗指人家去。","疲马懷澗泉，征衣犯霜露。","喧呼谿鸟驚，沙上或鶱翥。","娟娟东岑月，照耀独归慮。"]', '诗', 'shi', '', NULL, '早發西山 沈頌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dc0cf8a-c8ca-44cf-b97d-850c850e49dd', '送人還吳', '送人還吳', '46381756-1cf4-4973-8530-778cfa0eaa4c', '唐', '["人心不忘鄉，矧余客已久。","送君江南去，秋醉洛陽酒。","贈言幽徑蘭，別思河堤柳。","征帆暮風急，望望空延首。"]', '["人心不忘乡，矧余客已久。","送君江南去，秋醉洛陽酒。","贈言幽徑蘭，別思河堤柳。","征帆暮风急，望望空延首。"]', '诗', 'shi', '', NULL, '送人還吳 沈頌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42e6192d-b20f-4044-bc6e-c64ac79f75b6', '送金文學還日東', '送金文学還日东', '46381756-1cf4-4973-8530-778cfa0eaa4c', '唐', '["君家東海東，君去因秋風。","漫漫指鄉路，悠悠如夢中。","煙霧積孤島，波濤連太空。","冒險當不懼，皇恩措爾躬。"]', '["君家东海东，君去因秋风。","漫漫指乡路，悠悠如梦中。","煙霧積孤島，波濤連太空。","冒險當不懼，皇恩措爾躬。"]', '诗', 'shi', '', NULL, '送金文學還日東 沈頌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('329cf1e6-7104-40c2-83e6-81ca6d3e414c', '衛中作', '衛中作', '46381756-1cf4-4973-8530-778cfa0eaa4c', '唐', '["衛風愉豔宜春色，淇水清泠增暮愁。","總使榴花能一醉，終須萱草暫忘憂。"]', '["衛风愉豔宜春色，淇水清泠增暮愁。","總使榴花能一醉，終須萱草暫忘憂。"]', '诗', 'shi', '', NULL, '衛中作 沈頌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8bd0072-1837-46c0-beb3-d11bd2e81d62', '天長節', '天长節', '7fedd1b0-c0ec-4955-bf75-f9ebf0c44805', '唐', '["日月生天久，年年慶一迴。","時平祥不去，壽遠節長來。","連吹千家笛，同朝百郡杯。","願持金殿鏡，處處照遺才。"]', '["日月生天久，年年慶一迴。","时平祥不去，壽远節长来。","連吹千家笛，同朝百郡杯。","願持金殿镜，处处照遺才。"]', '诗', 'shi', '', NULL, '天長節 梁鍠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('689bd5c2-4117-4a59-8abc-6b26a1815d51', '長門怨', '长门怨', '7fedd1b0-c0ec-4955-bf75-f9ebf0c44805', '唐', '["妾命何偏薄，君王去不歸。","欲令遙見悔，樓上試春衣。","空殿看人入，深宮羨鳥飛。","翻悲因買賦，索鏡照空輝。"]', '["妾命何偏薄，君王去不归。","欲令遙见悔，楼上試春衣。","空殿看人入，深宮羨鸟飞。","翻悲因買賦，索镜照空輝。"]', '诗', 'shi', '', NULL, '長門怨 梁鍠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3e08068-4e0d-4626-b715-0dc046132245', '美人春臥', '美人春臥', '7fedd1b0-c0ec-4955-bf75-f9ebf0c44805', '唐', '["妾家巫峽陽，羅幌寢蘭堂。","曉日臨窗久，春風引夢長。","落釵仍挂鬢，微汗欲消黃。","縱使朦朧覺，魂猶逐楚王。"]', '["妾家巫峽陽，羅幌寢蘭堂。","晓日臨窗久，春风引梦长。","落釵仍挂鬢，微汗欲消黄。","縱使朦朧覺，魂猶逐楚王。"]', '诗', 'shi', '', NULL, '美人春臥 梁鍠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ba40038-c656-491f-b80b-5fc180d0b66c', '名姝詠', '名姝詠', '7fedd1b0-c0ec-4955-bf75-f9ebf0c44805', '唐', '["阿嬌年未多，弱體性能和。","怕重愁拈鏡，憐輕喜曳羅。","臨津雙洛浦，對月兩嫦娥。","獨有荆王殿，時時暮雨過。"]', '["阿嬌年未多，弱體性能和。","怕重愁拈镜，怜轻喜曳羅。","臨津雙洛浦，对月兩嫦娥。","独有荆王殿，时时暮雨過。"]', '诗', 'shi', '', NULL, '名姝詠 梁鍠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('909577b4-edeb-4ca5-a8eb-cdd9957df695', '豔女詞', '豔女词', '7fedd1b0-c0ec-4955-bf75-f9ebf0c44805', '唐', '["露井桃花發，雙雙燕並飛。","美人姿態裏，春色上羅衣。","自愛頻開鏡，時羞欲掩扉。","不知行路客，遙惹五香歸。"]', '["露井桃花發，雙雙燕並飞。","美人姿態裏，春色上羅衣。","自愛頻开镜，时羞欲掩扉。","不知行路客，遙惹五香归。"]', '诗', 'shi', '', NULL, '豔女詞 梁鍠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c98723b-cc97-47c0-ac65-5e749b81a129', '狷氏子', '狷氏子', '7fedd1b0-c0ec-4955-bf75-f9ebf0c44805', '唐', '["杏梁初照日，碧玉後堂開。","憶事臨妝笑，春嬌滿鏡臺。","含聲歌扉舉，顧影舞腰迴。","別有佳期處，青樓客夜來。"]', '["杏梁初照日，碧玉後堂开。","憶事臨妝笑，春嬌满镜台。","含声歌扉舉，顧影舞腰迴。","別有佳期处，青楼客夜来。"]', '诗', 'shi', '', NULL, '狷氏子 梁鍠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b18b37e0-813b-466a-946a-1204f4be0bc6', '戲贈歌者', '戲贈歌者', '7fedd1b0-c0ec-4955-bf75-f9ebf0c44805', '唐', '["白皙歌童子，哀音絕又連。","楚妃臨扇學，盧女隔簾傳。","曉燕喧喉裏，春鶯囀舌邊。","若逢漢武帝，還是李延年。"]', '["白皙歌童子，哀音絕又連。","楚妃臨扇学，盧女隔簾傳。","晓燕喧喉裏，春鶯囀舌邊。","若逢漢武帝，還是李延年。"]', '诗', 'shi', '', NULL, '戲贈歌者 梁鍠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86de7010-c682-4574-8bc7-f8d64cc3a2a7', '七夕汎舟', '七夕汎舟', '7fedd1b0-c0ec-4955-bf75-f9ebf0c44805', '唐', '["雲端有靈匹，掩映拂妝臺。","夜久應搖珮，天高響不來。","片歡秋始展，殘夢曉翻催。","却怨填河鵲，留橋又不迴。"]', '["云端有靈匹，掩映拂妝台。","夜久應搖珮，天高响不来。","片歡秋始展，殘梦晓翻催。","却怨填河鵲，留橋又不迴。"]', '诗', 'shi', '', NULL, '七夕汎舟 梁鍠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ed882b3-c64b-45d1-8d28-e738410abcb8', '崔駙馬宅詠畫山水扇', '崔駙马宅詠畫山水扇', '7fedd1b0-c0ec-4955-bf75-f9ebf0c44805', '唐', '["畫扇出秦樓，誰家贈列侯。","小含吳剡縣，輕帶楚揚州。","揜作山雲暮，搖成隴樹秋。","坐來傳與客，漢水又迴流。"]', '["畫扇出秦楼，誰家贈列侯。","小含吳剡縣，轻带楚揚州。","揜作山云暮，搖成隴樹秋。","坐来傳與客，漢水又迴流。"]', '诗', 'shi', '', NULL, '崔駙馬宅詠畫山水扇 梁鍠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb5da7a5-de8a-44d9-a2b0-cd8de2b53d97', '觀王美人海圖障子', '观王美人海圖障子', '7fedd1b0-c0ec-4955-bf75-f9ebf0c44805', '唐', '["宋玉東家女，常懷物外多。","自從圖渤海，誰爲覓湘娥。","白鷺栖脂粉，赬魴躍綺羅。","仍憐轉嬌眼，別恨一橫波。"]', '["宋玉东家女，常懷物外多。","自從圖渤海，誰爲覓湘娥。","白鷺栖脂粉，赬魴躍綺羅。","仍怜轉嬌眼，別恨一橫波。"]', '诗', 'shi', '', NULL, '觀王美人海圖障子 梁鍠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4528be7-0af5-492f-a0d9-321fdbe4fe9e', '聞百舌鳥', '闻百舌鸟', '7fedd1b0-c0ec-4955-bf75-f9ebf0c44805', '唐', '["百舌聞他郡，間關媚物華。","斂形藏一葉，分響出千花。","坐愛時褰幌，行藏或駐車。","不須應獨感，三載已辭家。"]', '["百舌闻他郡，间关媚物华。","斂形藏一葉，分响出千花。","坐愛时褰幌，行藏或駐车。","不須應独感，三載已辞家。"]', '诗', 'shi', '', NULL, '聞百舌鳥 梁鍠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aa1e99e-1895-425b-9937-afaf51067791', '省試方士進恆春草', '省試方士進恆春草', '7fedd1b0-c0ec-4955-bf75-f9ebf0c44805', '唐', '["東吳有靈草，生彼剡谿傍。","既亂莓苔色，仍連菡萏香。","掇之稱遠士，持以奉明王。","北闕顏彌駐，南山壽更長。","金膏徒騁妙，石髓莫矜良。","倘使霑涓滴，還游不死方。"]', '["东吳有靈草，生彼剡谿傍。","既亂莓苔色，仍連菡萏香。","掇之稱远士，持以奉明王。","北闕顏彌駐，南山壽更长。","金膏徒騁妙，石髓莫矜良。","倘使霑涓滴，還游不死方。"]', '诗', 'shi', '', NULL, '省試方士進恆春草 梁鍠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4050f23a-dc25-4e82-b858-07981528ed97', '代征人妻喜夫還', '代征人妻喜夫還', '7fedd1b0-c0ec-4955-bf75-f9ebf0c44805', '唐', '["征夫走馬發漁陽，少婦含嬌開洞房。","千日廢臺還挂鏡，數年塵面再新妝。","春風喜出今朝戶，明日虛眠昨夜牀。","莫道幽閨書信隔，還衣總是舊時香。"]', '["征夫走马發漁陽，少婦含嬌开洞房。","千日廢台還挂镜，數年塵面再新妝。","春风喜出今朝戶，明日虛眠昨夜牀。","莫道幽閨书信隔，還衣總是旧时香。"]', '诗', 'shi', '', NULL, '代征人妻喜夫還 梁鍠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc3a22df-2cf8-43a7-971b-f0dd9b51e6d6', '贈李中華', '贈李中华', '7fedd1b0-c0ec-4955-bf75-f9ebf0c44805', '唐', '["莫向嵩山去，神仙多誤人。","不如朝魏闕，天子重賢臣。"]', '["莫向嵩山去，神仙多誤人。","不如朝魏闕，天子重賢臣。"]', '诗', 'shi', '', NULL, '贈李中華 梁鍠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8190cf76-f2af-400c-a09d-8877e9b25a62', '詠木老人', '詠木老人', '7fedd1b0-c0ec-4955-bf75-f9ebf0c44805', '唐', '["刻木牽絲作老翁，雞皮鶴髮與真同。","須臾弄罷寂無事，還似人生一夢中。"]', '["刻木牽絲作老翁，雞皮鹤髮與真同。","須臾弄罷寂無事，還似人生一梦中。"]', '诗', 'shi', '', NULL, '詠木老人 梁鍠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69b236e5-0a72-4f82-a581-7d8d83122f6c', '句', '句', '7fedd1b0-c0ec-4955-bf75-f9ebf0c44805', '唐', '["堂高憑上望，宅廣乘車行。"]', '["堂高憑上望，宅廣乘车行。"]', '诗', 'shi', '', NULL, '句 梁鍠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('735c5425-745a-4a91-97e3-e6d262dce5fc', '客中作', '客中作', 'cd956eb1-e2b3-41c8-b357-a83ebe4c8a8b', '唐', '["書劒催人不暫閑，洛陽羈旅復秦關。","容顏歲歲愁邊改，鄉國時時夢裏還。"]', '["书劒催人不暫闲，洛陽羈旅复秦关。","容顏歲歲愁邊改，乡国时时梦裏還。"]', '诗', 'shi', '', NULL, '客中作 杜儼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b31f56ac-0f36-4a9b-9800-7db89789a1cf', '三月三日曲江侍宴', '三月三日曲江侍宴', '14e59a33-174c-4ab6-917b-a867358e203a', '唐', '["聖祖發神謀，靈符叶帝求。","一人光錫命，萬國荷時休。","雷解圜丘畢，雲需曲水遊。","岸花迎步輦，仙仗擁行舟。","睿藻天中降，恩波海外流。","小臣同品物，陪此樂皇猷。"]', '["聖祖發神謀，靈符叶帝求。","一人光錫命，万国荷时休。","雷解圜丘畢，云需曲水游。","岸花迎步輦，仙仗擁行舟。","睿藻天中降，恩波海外流。","小臣同品物，陪此乐皇猷。"]', '诗', 'shi', '', NULL, '三月三日曲江侍宴 趙良器 shi');
